  static short Word(float n){double v=n;if(v>=9223372036854775808d||v< -9223372036854775808d)throw new InvalidDataException("AFM metric outside the supported finite integer domain.");return unchecked((short)(long)Math.Truncate(v));}
  public static string FontName(string text){var rows=text.Replace("\r","").Split('\n');for(int n=0;n<Math.Min(16,rows.Length);n++)if(rows[n].StartsWith("FontName ",StringComparison.Ordinal)){string name=rows[n].Substring(9).Trim();if(name.Length==0)break;return name;}throw new InvalidDataException("FONTCONV-compatible AFM requires FontName in its first16 lines.");}
  public byte[] Convert(string text){string full=FontName(text),name=full.Length>28?full.Substring(0,28):full.PadRight(28);for(int n=0;n<162;n++)advance[n]=right[n]=1;bool started=false,special=false,ended=false;int seed=0;
