 public static class GeneratedPscFiles {
  public static Action<int> BeforeCommitForTests;
  public static void WritePair(string installed,string reusable,byte[] data){WritePair(installed,reusable,data,false);}
  public static void WritePair(string installed,string reusable,byte[] data,bool overwrite){
   installed=Path.GetFullPath(installed);reusable=Path.GetFullPath(reusable);if(String.Equals(installed,reusable,StringComparison.OrdinalIgnoreCase))throw new IOException("Choose a separate reusable PSC destination.");
   string[] paths={installed,reusable},temporary={null,null},backup={null,null};byte[][] previous=new byte[2][];bool[] committed={false,false},skip={false,false};bool success=false;
   try{for(int n=0;n<2;n++){if(File.Exists(paths[n]))previous[n]=File.ReadAllBytes(paths[n]);skip[n]=previous[n]!=null&&System.Linq.Enumerable.SequenceEqual(previous[n],data)&&(n==1||overwrite);if(skip[n])continue;if(previous[n]!=null&&!overwrite)throw new IOException("Existing PSC preserved: "+paths[n]+". Enable overwrite explicitly or choose a different destination.");string directory=Path.GetDirectoryName(paths[n]);temporary[n]=Path.Combine(directory,".ScoreModern-"+Guid.NewGuid().ToString("N")+".tmp");if(previous[n]!=null)backup[n]=Path.Combine(directory,".ScoreModern-"+Guid.NewGuid().ToString("N")+".psc-backup");using(var file=new FileStream(temporary[n],FileMode.CreateNew,FileAccess.Write,FileShare.None)){file.Write(data,0,data.Length);file.Flush(true);}}
    for(int n=0;n<2;n++){if(BeforeCommitForTests!=null)BeforeCommitForTests(n);if(skip[n]){if(!File.Exists(paths[n])||!System.Linq.Enumerable.SequenceEqual(File.ReadAllBytes(paths[n]),data))throw new IOException("Reusable PSC changed during creation.");continue;}if(previous[n]==null){File.Move(temporary[n],paths[n]);}else{if(!File.Exists(paths[n])||!System.Linq.Enumerable.SequenceEqual(File.ReadAllBytes(paths[n]),previous[n]))throw new IOException("PSC changed before overwrite: "+paths[n]);File.Replace(temporary[n],paths[n],backup[n]);}committed[n]=true;}success=true;
   }catch(Exception error){var recovery=new System.Collections.Generic.List<string>();for(int n=1;n>=0;n--)if(committed[n])try{if(File.Exists(paths[n])&&System.Linq.Enumerable.SequenceEqual(File.ReadAllBytes(paths[n]),data)){if(previous[n]==null)File.Delete(paths[n]);else File.Replace(backup[n],paths[n],null);}else if(backup[n]!=null)recovery.Add(backup[n]);}catch(Exception){if(backup[n]!=null)recovery.Add(backup[n]);}if(recovery.Count>0)throw new IOException("PSC transaction failed. Recovery copies retained: "+String.Join(", ",recovery.ToArray()),error);throw;
   }finally{for(int n=0;n<2;n++){if(temporary[n]!=null&&File.Exists(temporary[n]))try{File.Delete(temporary[n]);}catch(IOException){}if(success&&backup[n]!=null&&File.Exists(backup[n]))try{File.Delete(backup[n]);}catch(IOException){}}}
  }

 }
